// План specs/job-dates.md 1.1 (кейсы .qa/tests/job-dates/JDT-01, JDT-02). Admin, компания «test», десктоп, EN, браузер в America/New_York.
// @writes: создаёт работу «QA-AUTO reclick #664ccb …» (QA-quota client, БЕЗ техников) и в finally переводит её в Cancelled.
// send-sms перехватывается и обрывается. В finally selected-company-id = test.
import { test, expect } from '@playwright/test';
import {
  ADMIN_STATE, US_TZ, T, blockSmsSending, cancelJobs, columnIndex, createQaJob, dateButton, expectNoSmsSent, jobRow,
  openCalendar, openJobsList, restoreCompany, selectedDay, shortEn, todayUs, useLang,
} from './job-dates-helpers';
import { openNewJob } from '../dispatch-sms/dispatch-helpers';

test.use({ storageState: ADMIN_STATE, timezoneId: US_TZ });

test.describe('Job date: re-clicking the selected day keeps the date (#664ccb)', () => {
  test('New Job and Job Details: re-click on the selected day keeps the date; saved job has a date, is in Schedule Day and shows "Today" in Jobs #664ccb @desktop @writes', async ({ page }) => {
    test.setTimeout(240_000);
    await useLang(page, 'en');
    const smsHits = await blockSmsSending(page);
    const today = todayUs();
    const created: string[] = [];
    try {
      // 1. New Job: в поле Date уже сегодня; повторный клик по выбранному дню не сбрасывает дату.
      // Источник: «מה רצוי» — לחיצה על היום שכבר נבחר לא מבטלת אותו; комментарий программиста п.1.
      await openNewJob(page, 'en');
      await expect(dateButton(page)).toHaveText(new RegExp(`^\\s*${shortEn(today)}\\b`));
      let cal = await openCalendar(page);
      await selectedDay(cal).click();
      if (await cal.isVisible()) await page.keyboard.press('Escape');
      await expect(dateButton(page)).toHaveText(new RegExp(`^\\s*${shortEn(today)}\\b`));
      await expect(page.getByText(T.en.pickDate, { exact: true })).toHaveCount(0);

      // 2. Сохранить работу (форма заполняется заново в createQaJob; дата — сегодня по умолчанию).
      const title = `QA-AUTO reclick #664ccb ${Date.now().toString(36)}`;
      const job = await createQaJob(page, title);
      created.push(job.url);

      // 3. Job Details: дата есть (не «Pick a date») и после перезагрузки.
      await page.goto(job.url);
      await expect(dateButton(page)).toBeVisible({ timeout: 30_000 });
      await expect(dateButton(page)).not.toHaveText(/Pick a date/);
      await expect(dateButton(page)).toContainText(shortEn(today));

      // 4. Job Details: повторный клик по выбранному дню тоже не сбрасывает дату (комментарий программиста п.1).
      cal = await openCalendar(page);
      await selectedDay(cal).click();
      if (await cal.isVisible()) await page.keyboard.press('Escape');
      await expect(dateButton(page)).toContainText(shortEn(today));
      await page.goto(job.url);
      await expect(dateButton(page)).toContainText(shortEn(today));

      // 5. Schedule → Day → Today: работа видна (источник: «מה קיים» — ב-Schedule העבודה לא מופיעה; JDT-02).
      await page.getByRole('link', { name: 'Schedule', exact: true }).first().click();
      await expect(page.getByRole('heading', { name: 'Schedule', exact: true })).toBeVisible({ timeout: 30_000 });
      await page.getByRole('tab', { name: 'Day', exact: true }).or(page.getByRole('button', { name: 'Day', exact: true })).first().click();
      await page.getByRole('button', { name: 'Today', exact: true }).click();
      await expect(page.locator('main').getByText(title, { exact: true })).toBeVisible({ timeout: 30_000 });

      // 6. Jobs: у работы реальная сегодняшняя дата и «Today» (а не «Not scheduled»).
      await openJobsList(page);
      const row = jobRow(page, job.code);
      await expect(row).toBeVisible();
      const idx = await columnIndex(page, T.en.scheduled);
      const cell = row.locator('td, [role="cell"]').nth(idx);
      await expect(cell).toHaveText(new RegExp(`${shortEn(today)},\\s*${today.y}\\s*Today`));
      await expect(cell).not.toContainText(T.en.notScheduled);
    } finally {
      await cancelJobs(page, created);
      await restoreCompany(page);
    }
    expectNoSmsSent(smsHits);
  });
});
